// Log low-confidence escalation event
const data = $input.first().json;

const diagnosis = data.diagnosis || data;
const confidence = data.confidence || diagnosis.confidence || 0;
const confPercent = Math.round(confidence * 100);

const escalation = {
  escalation_id: `ESC-${Date.now()}`,
  event: 'low_confidence_escalation',
  timestamp: new Date().toISOString(),
  request_id: data.request_id || '',

  // Diagnosis details
  disease_name: diagnosis.disease_name || 'Unknown',
  confidence: confidence,
  confidence_percent: confPercent,
  treatment: diagnosis.treatment || '',
  pesticide: diagnosis.pesticide || '',

  // Location
  location: diagnosis.location || { lat: null, lng: null },

  // Priority (lower confidence = higher priority)
  priority: confPercent < 30 ? 'CRITICAL' : confPercent < 50 ? 'HIGH' : 'MEDIUM',

  // Escalation metadata
  assigned_to: 'PAU Agronomist (auto-assign)',
  escalation_channel: 'internal',
  requires_field_visit: confPercent < 30,
  status: 'pending_review'
};

console.log('[Krishi-Sarthi ESCALATION]', JSON.stringify({
  id: escalation.escalation_id,
  disease: escalation.disease_name,
  confidence: `${confPercent}%`,
  priority: escalation.priority
}));

return [{ json: escalation }];

// Simulate PAU agronomist alert
const esc = $input.first().json;

// In production, this would:
// 1. Send email to assigned PAU agronomist
// 2. Post to internal Slack/Teams channel  
// 3. Create a ticket in agronomist queue
// 4. Trigger SMS to on-call expert for CRITICAL priority

const alert = {
  alert_type: 'pau_agronomist',
  escalation_id: esc.escalation_id,
  disease: esc.disease_name,
  confidence: `${esc.confidence_percent}%`,
  priority: esc.priority,
  requires_field_visit: esc.requires_field_visit,
  location: esc.location,

  // Simulated expert assignment
  assigned_expert: {
    name: 'Dr. Ramandeep Singh',
    department: 'Plant Pathology, PAU Ludhiana',
    phone: '+91 98765 00000',
    email: 'agronomist@pau.edu'
  },

  alert_sent_at: new Date().toISOString(),
  expected_response_time: esc.priority === 'CRITICAL' ? '2 hours' : '24 hours',
  status: 'alert_sent'
};

console.log('[Krishi-Sarthi EXPERT ALERT]', JSON.stringify({
  expert: alert.assigned_expert.name,
  priority: alert.priority,
  disease: alert.disease,
  response_time: alert.expected_response_time
}));

return [{ json: alert }];
